import { test, expect, vi } from 'vitest';
const store: Record<string,string> = {};
(globalThis as any).window = { localStorage: { getItem: (k:string)=>store[k] ?? null, setItem: (k:string,v:string)=>{store[k]=v;} } };
import { readStoredTheme, writeStoredTheme, THEME_STORAGE_KEY } from './theme/themeStorage';
test('persist', () => {
  expect(readStoredTheme()).toBe('light');
  writeStoredTheme('dark'); expect(store[THEME_STORAGE_KEY]).toBe('dark'); expect(readStoredTheme()).toBe('dark');
  store[THEME_STORAGE_KEY] = 'garbage'; expect(readStoredTheme()).toBe('light');
  (globalThis as any).window.localStorage.getItem = () => { throw new Error('blocked'); };
  expect(readStoredTheme()).toBe('light');
});
EOF
npx vitest run src/__tmp.test.ts 2>&1 | tail -6; rm src/__tmp.test.ts
